INSERT INTO `submissions` VALUES (1,'','BCS23090016','','BCS','SEP/2025','system-dev','Automated FYP Management and Marking Portal','Automated FYP Management and Marking Portal\n\nThe evaluation of a student’s Final Year Project (FYP) is one of the most integral parts of any undergraduate programme, as it assesses students’ capability of applying their knowledge and\nskills acquired throughout their studies into a project. As of today, the process of managing the\nmarks of a student’s FYP often involves cross-checking of rubrics as well as calculating marks via\nExcel spreadsheets. This process is typically handled by university lecturers and FYP coordinators\nwho are responsible for overseeing the evaluation process and ensuring that grading is aligned with\nthe intended rubrics and course outcomes (COs).','With the growing number of students registering each semester, FYP coordinators find it\nincreasingly inefficient to record and manage hundreds of student marks. Although Excel spreadsheets are used to calculate marks of students\' performance, the files are not centralised, which makes it difficult to access and manage records across multiple semesters. This will also\nlead to difficulties in tracking and retrieving previous records.','The proposed Automated FYP Management and Marking Portal holds significant academic and administrative value. A Final Year Project is one of the most critical components of any undergraduate programme, as it assesses students’ capability to do research and analytical thinking. However, as student enrolment increases and assessment criteria evolve, managing and marking these projects through manual methods has become increasingly inefficient. Therefore, the development of a unified and automated marking system directly supports institutional goals of academic quality assurance, operational efficiency and digital transformation.','The target users are primarily Final Year Project coordinators who are responsible for\ncoordinating and consolidating the evaluation of students’ Final Year Projects. As the number of students undertaking Final Year Projects increases in UTS, coordinators are\nfacing challenges managing large volumes of records. This portal is designed to support\nthese coordinators in handling the increasing workload by providing a more efficient and\nreliable tool for evaluating Final Year Projects.','Existing systems include UNIMAS FCSIT FYP Portal, The University of Auckland Project Portal and Final year Project Portal of University of the Punjab','-Editable marking rubrics, managed by portal admin. \n-Automated calculation of final marks based on rubrics.\n-Exportable final marks in predefined formats.\n-Dedicated dashboard for grade distribution.',NULL,'approved','2026-05-22 09:38:38.058827','2026-05-22 10:45:30.410484',NULL,3,18),(2,'','BCS23090021','','BCS','SEP/2025','system-dev','Timetabling in the FYP Management and Marking Portal','Timetabling in the FYP Management and MarkingPortal','X','X','X','X','X',NULL,'approved','2026-05-22 09:39:38.754127','2026-05-22 10:45:46.405432',NULL,7,18),(3,'','BCS23020036','','BCS','SEP/2025','research','Intelligent FYP Submission and Feedback Management Module','Intelligent FYP Submission and Feedback Management Module','x','x','x','x','x',NULL,'approved','2026-05-22 09:40:42.996030','2026-05-28 20:25:19.756921',NULL,2,16),(4,'','BCS23090015','','BCS','SEP/2025','research','SCM Career Bridge: A Centralized Internship Platform for the School of Computing & Creative Media','SCM Career Bridge: A Centralized Internship Platform for the School of Computing & Creative Media','x','x','x','x','x',NULL,'approved','2026-05-22 09:45:17.434695','2026-05-22 09:51:01.046321',NULL,5,18),(5,'','BCS2402001','','BCS','SEP/2025','system-dev','Automatic Detection of Road Damage (Pothole Detection)in streets.','Automatic Detection of Road Damage (Pothole Detection)in streets.','x','x','x','x','x',NULL,'approved','2026-05-22 14:37:08.704592','2026-05-28 20:03:59.507169',NULL,10,18),(6,'','BCS24020050','','BCS','SEP/2025','system-dev','AI-Based Lost and Found Image Recognition System for  Campus Use','AI-Based Lost and Found Image Recognition System for  Campus Use','X','X','X','X','X',NULL,'approved','2026-05-22 14:37:43.339110','2026-05-22 14:38:04.894160',NULL,9,18),(7,'','jawjing','','BCS','SEP/2025','system-dev','Software project','1','1','1','1','1','1',NULL,'pending','2026-06-16 09:24:38.859303','2026-06-16 09:24:38.859303',NULL,6,17),(8,'','kimyu','','BCS','SEP/2025','system-dev','Smart Dustbin Sorter','1','1','1','1','1','1',NULL,'revision','2026-06-16 09:25:29.939302','2026-06-16 11:20:27.980510',NULL,8,17);
