CREATE TABLE `rubrics_marks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `student_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `student_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `supervisor` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `examiner` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `project_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `course` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fyp_stage` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `marks_data` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `section_totals` longtext COLLATE utf8mb4_general_ci,
  `co_attainment` longtext COLLATE utf8mb4_general_ci,
  `criterion_marks` longtext COLLATE utf8mb4_general_ci,
  `total_score` decimal(5,2) DEFAULT NULL,
  `evaluated_by` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `evaluated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `template_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `programme_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_rubrics_marks_student_id` (`student_id`),
  KEY `idx_rubrics_marks_evaluated_by` (`evaluated_by`),
  KEY `idx_rubrics_marks_status` (`status`),
  KEY `idx_rubrics_marks_course` (`course`),
  KEY `idx_rubrics_marks_fyp_stage` (`fyp_stage`),
  KEY `rubrics_marks_template_id_33e3eafc_fk_rubrics_templates_id` (`template_id`),
  KEY `rubrics_marks_programme_id_67d3ad76_fk_api_programme_id` (`programme_id`),
  CONSTRAINT `rubrics_marks_programme_id_67d3ad76_fk_api_programme_id` FOREIGN KEY (`programme_id`) REFERENCES `api_programme` (`id`),
  CONSTRAINT `rubrics_marks_template_id_33e3eafc_fk_rubrics_templates_id` FOREIGN KEY (`template_id`) REFERENCES `rubrics_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
