INSERT INTO `rubrics_marks` VALUES (6,'BCS23090016','Darren Eng Zi Wei','Khairunnisa Ibrahim','','Automated FYP Management and Marking Portal','CSS3714 Final Year Project I','FYP1','{\"title\":\"CSS3714 Final Year Project I Marking Rubric (BCS) Ver. 7\",\"course\":\"CSS3714 Final Year Project I\",\"fyp_stage\":\"FYP1\",\"student\":{\"name\":\"Darren Eng Zi Wei\",\"id\":\"BCS23090016\",\"supervisor\":\"KhairunnisaIlrahim\",\"examiner\":\"\",\"project\":\"Automated FYP Management and Marking Portal\"},\"clos\":[\"CO1: Acknowledge the continuous development of knowledge and the needs of self-upgrading.\",\"CO2: Define the objectives of a research.\",\"CO3: Compare reviews on previous research.\",\"CO4: Carry out methodology to collect data for conducting research.\",\"CO5: Prepare the schedule of a research.\",\"CO6: Produce a research proposal.\"],\"section_order\":[\"presentation\",\"project_outcome\",\"sv_evaluation\",\"report\"],\"section_meta\":{\"presentation\":{\"label\":\"Part I Presentation\",\"mark_total\":26,\"total_weight\":13,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"Supervisor (S) marks \\/100*weight + Moderator (M) marks\\/100 * weight\"},\"project_outcome\":{\"label\":\"Project Outcome\",\"mark_total\":25,\"total_weight\":12.5,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"Supervisor (S) marks \\/100*weight + Moderator (M) marks\\/100 * weight\"},\"sv_evaluation\":{\"label\":\"SV Evaluation\",\"mark_total\":24,\"total_weight\":24,\"evaluators\":[\"s\"],\"compilation\":\"\"},\"report\":{\"label\":\"Report\",\"mark_total\":25,\"total_weight\":12.5,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"\"}},\"presentation\":[{\"item\":\"Overall Delivery\",\"co\":\"CO1\",\"weight\":1.5,\"levels\":[\"Presentation lack of structure, background not properly introduced, and proposed solution does not seem to be linked.\",\"Presentation organization seems adequate although linkage between background of project with proposed solution is unclear.\",\"Clear organizati